d=read('/input/data')
n=d['nodes']
e=d['edges']
lev={}
left=list(n)
while len(left)>0:
    progress=[]
    for x in left:
        ready=True
        best=0
        for a in e:
            if a['v']==x:
                if a['u'] not in lev:
                    ready=False
                else:
                    best=max(best,lev[a['u']]+1)
        if ready:
            lev=putmap(lev,x,best)
            progress=progress+[x]
    left=[x for x in left if x not in progress]
    if len(progress)==0:
        break
m=[]
if len(n)>0:
    for k in range(max(list(lev.values()))+1):
        m=m+[sorted([x for x in n if lev[x]==k])]
result={'main':m}
